head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin._checkValue = function() {
    return localStorage.getItem("log").indexOf("rowIndex : 0, colIndex : 1, dateStr : 20160714, dateObj : Thu Jul 14 2016") != -1;
}
scwin.setVal = function() {
    scwin.fireDbClick(WebSquare.wUnit.getDomById('gridView1_cell_0_1'));
}
scwin.checkVal = function() {
    return scwin._checkValue();
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 name2항목값에 날짜를 입력한다.
    //1. Run the sample file and enter the date in the value of the name2 entry.
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1__col2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_'+$p.id+'gridView1__col2_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'G_'+$p.id+'gridView1__col2_calendar_selectbox_year_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'G_'+$p.id+'gridView1__col2_calendar_selectbox_year_itemTable_38').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'G_'+$p.id+'gridView1__col2_calendar_selectbox_month_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'G_'+$p.id+'gridView1__col2_calendar_selectbox_month_itemTable_6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'G_'+$p.id+'gridView1__col2_calendar_cell_2_4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 알림창에 정상적인 결과가 보여진다.rowindex:0 colIndex:1 dateStr:20160714 dateObj:Thu Jul 14 2016 00:00:00 GMT +0900(대한민국표준시)
    //1. The normal result is displayed in the notification window. rowindex: 0 colIndex: 1 dateStr: 20160714 dateObj: Thu Jul 14 2016 00:00:00 GMT +0900 (Korea Standard Time)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('log')");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 28-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
